raw = [
    {"vendor": "edr", "data": {"DeviceName": "LAPTOP-17", "SHA256": "ab12", "Severity": "High"}},
    {"vendor": "siem", "data": {"host": "laptop-17", "file_hash": "AB12", "sev": 3}},
    {"vendor": "edr", "data": {"DeviceName": "BUILD-02", "SHA256": "cd34", "Severity": "Low"}},
]
SEV = {"Low": 1, "Medium": 2, "High": 3}

def normalize(e):
    d = e["data"]
    if e["vendor"] == "edr":
        return {"host": d["DeviceName"].lower(), "hash": d["SHA256"].lower(), "sev": SEV[d["Severity"]], "src": "edr"}
    return {"host": d["host"].lower(), "hash": d["file_hash"].lower(), "sev": d["sev"], "src": "siem"}

CTI = {"ab12": "known-malware"}          # 위협 정보 조회 결과(가상)
ASSET = {"laptop-17": "finance", "build-02": "ci"}
cases = {}
for ev in map(normalize, raw):
    ev["cti"] = CTI.get(ev["hash"], "unknown")
    ev["owner"] = ASSET.get(ev["host"], "?")
    key = (ev["host"], ev["hash"])      # 같은 호스트·같은 파일 = 한 건
    c = cases.setdefault(key, {**ev, "sources": []})
    c["sources"].append(ev["src"])
    c["sev"] = max(c["sev"], ev["sev"])
for c in cases.values():
    route = "SOC 즉시" if c["cti"] == "known-malware" and c["sev"] >= 3 else "자동 종결 후보"
    print(c["host"], c["hash"], c["cti"], c["owner"], c["sources"], "->", route)
print(f"경보 {len(raw)}건 -> 사건 {len(cases)}건")
# laptop-17 ab12 known-malware finance ['edr', 'siem'] -> SOC 즉시
# build-02 cd34 unknown ci ['edr'] -> 자동 종결 후보
# 경보 3건 -> 사건 2건

import time
calls = {"n": 0}

def ticket_api():
    calls["n"] += 1
    if calls["n"] < 3:
        raise TimeoutError("503")
    return "TICKET-981"

def with_retry(fn, tries=4, base=0.1):
    for i in range(tries):
        try:
            return fn()
        except TimeoutError as e:
            wait = base * 2 ** i
            print(f"{i+1}회 실패({e}) -> {wait:.1f}초 뒤 다시")
            time.sleep(wait)
    raise RuntimeError("포기 - 사람에게 넘김")

print("결과:", with_retry(ticket_api))
# 1회 실패(503) -> 0.1초 뒤 다시
# 2회 실패(503) -> 0.2초 뒤 다시
# 결과: TICKET-981
